q07-all-any-null-price.code:
-- Zapytanie 1
SELECT e.last_name FROM employees e
WHERE  e.salary > ALL (SELECT p.list_price FROM products p);

-- Zapytanie 2
SELECT e.last_name FROM employees e
WHERE  e.salary > ANY (SELECT p.list_price FROM products p);

q07-empty-subquery-in-not-in.code:
-- Zapytanie 1
SELECT e.last_name FROM employees e
WHERE  e.department_id IN (SELECT d.department_id FROM departments d WHERE 1 = 0);

-- Zapytanie 2
SELECT e.last_name FROM employees e
WHERE  e.department_id NOT IN (SELECT d.department_id FROM departments d WHERE 1 = 0);
